//! Drift: owned vault files that changed outside the renderer.
//!
//! The supported contract is: **do not edit generated notes directly; use
//! `Notes/` (or `Boards/`, `Inbox/`) or controlled mutations.** Drift
//! detection is the safety net for edits that happen anyway. It preserves the
//! edits it observes. It cannot coordinate a viewer's unsaved buffer or a
//! sync client that writes between the inspection and the rename, so it does
//! not guarantee to preserve every racing edit.
//!
//! An owned path drifts when what is there is not the bytes the manifest
//! records as last generated (or a hash an unfinished render intended):
//!
//! | Kind            | Observed at an owned path                                    |
//! |-----------------|--------------------------------------------------------------|
//! | `edited`        | other bytes (a body edit, or a property edit made through a  |
//! |                 | viewer's table or board, which rewrites the note's           |
//! |                 | frontmatter), or a link, folder or special file              |
//! | `missing`       | nothing: the file was deleted                                |
//! | `renamed`       | nothing, and a file elsewhere in the vault is the same file: |
//! |                 | the same bytes, or a note whose `inv_id` property names the  |
//! |                 | record the path projects                                     |
//! | `conflict_copy` | the generated bytes, with a sync client's conflict copy      |
//! |                 | beside it                                                    |
//!
//! A conflict copy is recognized by name only, without naming any client: a
//! file in the same folder that is neither owned nor planned, whose name is
//! the owned file's stem followed by a character that is not a letter or
//! digit, and whose remainder contains `conflict` in any case. So for
//! `q_1.md`: `q_1 (conflicted copy 2026-01-02).md`, `q_1.sync-conflict-x.md`
//! and `q_1.md.conflict` are copies; `q_12 (conflict).md`, `q_1 (1).md` and
//! `q_1 2.md` are not. Copies named without the word are not detected as
//! copies; outside the human-owned roots they are still reported as unknown
//! files. Every conflict copy found beside a path is listed, whatever its kind.
//!
//! What a render does with a drifted path:
//!
//! - It never writes, replaces or deletes it, and never deletes or renames the
//!   edited file, the moved file or a conflict copy. A deleted or moved file
//!   is not recreated, so a reader never sees two notes for one record. The
//!   path stays owned at the last generated hash, so it is diagnosed again on
//!   every render until it is reconciled: putting the generated bytes back,
//!   removing the conflict copies, or an explicit disposition.
//! - The content it would have written is retained in the conflicts area,
//!   `local/conflicts/<generation>/<path>`, and the record names that file
//!   ([`Drift::conflict`]). A later render whose would-be content is the same
//!   reuses that file instead of writing another copy.
//! - The path is recorded in the manifest ([`crate::Manifest::drift`]), so
//!   [`crate::vault_status`] reports it without reading the vault, and in
//!   [`crate::RenderReport::drift`].
//! - Every other file renders as usual. Drift never stops a render and never
//!   changes canonical state; nothing is inferred from the edited Markdown.
//!
//! One exception keeps a killed render from looking like a deletion: when the
//! manifest says a render was `updating` (killed before it recorded its
//! outcome), an owned file found missing may have been removed by that render
//! itself, so it is created again unless it was already recorded as drifted.

use std::{
    collections::{BTreeMap, BTreeSet},
    fs::File,
    io::Read,
    os::fd::{AsFd, OwnedFd},
};

use investigation_core::{identity::Id, wire::Digest};
use investigation_store::{Workspace, journal::hash_bytes};
use rustix::{
    fs::{AtFlags, Dir, FileType, Mode, OFlags, fstat, fsync, mkdirat, openat, statat},
    io::Errno,
};

use crate::{
    Action, Decision, Manifest, OnDisk, Ownership, PlanEntry, PlanPath, PublishReport, Publisher,
    Refusal, RenderError, RenderPlan,
    lock::open_local,
    marker,
    publish::{Walk, write_bytes_atomically},
};

/// Workspace-relative folder holding the generated versions a render
/// withheld from drifted paths.
pub const CONFLICTS_DIR: &str = "local/conflicts";

/// Files larger than this are never read while looking for a moved note.
const MAX_CANDIDATE_BYTES: u64 = 16 << 20;

/// How an owned path drifted. See the module documentation.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
pub enum DriftKind {
    Edited,
    Missing,
    Renamed,
    ConflictCopy,
}

impl DriftKind {
    pub const ALL: [Self; 4] = [
        Self::Edited,
        Self::Missing,
        Self::Renamed,
        Self::ConflictCopy,
    ];

    pub const fn as_str(self) -> &'static str {
        match self {
            Self::Edited => "edited",
            Self::Missing => "missing",
            Self::Renamed => "renamed",
            Self::ConflictCopy => "conflict_copy",
        }
    }

    pub fn parse(text: &str) -> Option<Self> {
        Self::ALL.into_iter().find(|kind| kind.as_str() == text)
    }
}

/// One drifted owned path.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Drift {
    /// The owned vault path.
    pub path: PlanPath,
    pub kind: DriftKind,
    /// The last generated hash the path is owned at.
    pub expected: Digest,
    /// The hash of the regular file found at the path, when there is one.
    pub observed: Option<Digest>,
    /// The record the path projects, when it projects exactly one.
    pub projects: Option<Id>,
    /// The hash of the content the render withheld from the path; `None`
    /// when nothing was withheld (a retired path, or a conflict copy beside
    /// a file that already holds the planned bytes).
    pub generated: Option<Digest>,
    /// Workspace-relative path of the withheld content in the conflicts
    /// area, `local/conflicts/<generation>/<path>`.
    pub conflict: Option<String>,
    /// Vault-relative paths where the file was found moved to, sorted.
    pub renamed_to: Vec<String>,
    /// Vault-relative paths of conflict copies beside the path, sorted.
    pub copies: Vec<String>,
    /// The generation whose render first diagnosed the drift.
    pub since: String,
}

/// Whether the file name `candidate` is a sync client's conflict copy of the
/// file named `owned` in the same folder. See the module documentation.
pub fn is_conflict_copy(candidate: &str, owned: &str) -> bool {
    if candidate == owned {
        return false;
    }
    let stem = match owned.rsplit_once('.') {
        Some((stem, _)) if !stem.is_empty() => stem,
        _ => owned,
    };
    let Some(rest) = candidate.strip_prefix(stem) else {
        return false;
    };
    rest.chars()
        .next()
        .is_some_and(|next| !next.is_alphanumeric())
        && rest.to_lowercase().contains("conflict")
}

/// Conflict copies beside owned files, found before publishing.
#[derive(Debug, Default)]
pub(crate) struct Survey {
    copies: BTreeMap<PlanPath, Vec<String>>,
}

impl Survey {
    fn holds(&self, path: &PlanPath) -> bool {
        self.copies.contains_key(path)
    }
}

/// List the folder of every owned path once and match conflict copies.
/// Read-only. Folders that are missing or reached through a link are
/// skipped.
pub(crate) fn survey(
    publisher: &Publisher<'_>,
    manifest: &Manifest,
    plan: &RenderPlan,
) -> Result<Survey, RenderError> {
    let planned: BTreeSet<&str> = plan
        .entries()
        .iter()
        .map(|entry| entry.path().as_str())
        .collect();
    let mut by_directory: BTreeMap<Vec<&str>, Vec<&PlanPath>> = BTreeMap::new();
    for record in manifest.owned() {
        let mut components: Vec<&str> = record.path.components().collect();
        components.pop();
        by_directory
            .entry(components)
            .or_default()
            .push(&record.path);
    }
    let mut survey = Survey::default();
    for (parents, paths) in &by_directory {
        let Walk::Directory(directory) = publisher.walk(paths[0], parents, false)? else {
            continue;
        };
        let prefix = parents.join("/");
        let label = if prefix.is_empty() { "vault" } else { &prefix };
        let mut listing =
            Dir::read_from(&directory).map_err(|error| RenderError::io(label, error))?;
        while let Some(item) = listing.read() {
            let item = item.map_err(|error| RenderError::io(label, error))?;
            let Ok(name) = item.file_name().to_str() else {
                continue;
            };
            if name.starts_with('.') {
                continue;
            }
            let relative = if prefix.is_empty() {
                name.to_owned()
            } else {
                format!("{prefix}/{name}")
            };
            if manifest.owns(&relative) || planned.contains(relative.as_str()) {
                continue;
            }
            let Some(owner) = paths
                .iter()
                .filter(|path| is_conflict_copy(name, path.file_name()))
                .max_by_key(|path| path.file_name().len())
            else {
                continue;
            };
            let mut kind = item.file_type();
            if kind == FileType::Unknown {
                kind = match statat(&directory, name, AtFlags::SYMLINK_NOFOLLOW) {
                    Ok(stat) => FileType::from_raw_mode(stat.st_mode),
                    Err(Errno::NOENT) => continue,
                    Err(error) => return Err(RenderError::io(relative, error)),
                };
            }
            if kind != FileType::Directory {
                survey
                    .copies
                    .entry((*owner).clone())
                    .or_default()
                    .push(relative);
            }
        }
    }
    for copies in survey.copies.values_mut() {
        copies.sort();
    }
    Ok(survey)
}

/// The ownership a working-vault render publishes under: the manifest's
/// rules, and no write or removal at a path with a conflict copy beside it.
pub(crate) struct Guard<'a> {
    pub manifest: &'a Manifest,
    pub survey: &'a Survey,
}

impl Guard<'_> {
    fn hold(&self, path: &PlanPath, decision: Decision) -> Decision {
        match decision {
            Decision::Write | Decision::Remove if self.survey.holds(path) => {
                Decision::Refuse(Refusal::Drifted)
            }
            decision => decision,
        }
    }
}

impl Ownership for Guard<'_> {
    fn decide(&self, entry: &PlanEntry, on_disk: &OnDisk) -> Decision {
        self.hold(entry.path(), self.manifest.decide(entry, on_disk))
    }

    fn retired(&self, plan: &RenderPlan) -> Vec<PlanPath> {
        self.manifest.retired(plan)
    }

    fn decide_removal(&self, path: &PlanPath, on_disk: &OnDisk) -> Decision {
        self.hold(path, self.manifest.decide_removal(path, on_disk))
    }
}

/// The drift records for every owned path `report` reached, from the
/// outcomes and the survey. Missing files are then looked for elsewhere in
/// the vault, the human-owned roots included. Read-only; `conflict` is not
/// set yet (see [`retain`]).
pub(crate) fn diagnose(
    publisher: &Publisher<'_>,
    manifest: &Manifest,
    plan: &RenderPlan,
    report: &PublishReport,
    survey: &Survey,
) -> Result<Vec<Drift>, RenderError> {
    let entries: BTreeMap<&PlanPath, &PlanEntry> = plan
        .entries()
        .iter()
        .map(|entry| (entry.path(), entry))
        .collect();
    let mut drifts = Vec::new();
    for outcome in &report.outcomes {
        let path = &outcome.path;
        let Some(record) = manifest.get(path) else {
            continue;
        };
        let copies = survey.copies.get(path).cloned().unwrap_or_default();
        let withheld = matches!(
            outcome.action,
            Action::Refused(Refusal::Drifted | Refusal::NotARegularFile)
        );
        let kind = match &outcome.previous {
            _ if !withheld && copies.is_empty() => continue,
            _ if !withheld => DriftKind::ConflictCopy,
            Some(OnDisk::Absent) => DriftKind::Missing,
            Some(OnDisk::Regular { sha256 })
                if !copies.is_empty() && manifest.accepts(path, sha256) =>
            {
                DriftKind::ConflictCopy
            }
            _ => DriftKind::Edited,
        };
        let observed = match &outcome.previous {
            Some(OnDisk::Regular { sha256 }) => Some(sha256.clone()),
            _ => None,
        };
        let generated = entries
            .get(path)
            .filter(|entry| withheld && observed.as_ref() != Some(entry.sha256()))
            .map(|entry| entry.sha256().clone());
        drifts.push(Drift {
            path: path.clone(),
            kind,
            expected: record.sha256.clone(),
            observed,
            projects: record.projects,
            generated,
            conflict: None,
            renamed_to: Vec::new(),
            copies,
            since: manifest.drifted(path).map_or_else(
                || plan.generation().id().to_owned(),
                |previous| previous.since.clone(),
            ),
        });
    }
    find_moved(publisher, manifest, plan, &mut drifts)?;
    Ok(drifts)
}

/// Mark missing paths whose file is found elsewhere in the vault as renamed.
fn find_moved(
    publisher: &Publisher<'_>,
    manifest: &Manifest,
    plan: &RenderPlan,
    drifts: &mut [Drift],
) -> Result<(), RenderError> {
    let missing: Vec<usize> = (0..drifts.len())
        .filter(|&index| drifts[index].kind == DriftKind::Missing)
        .collect();
    if missing.is_empty() {
        return Ok(());
    }
    let extension = |path: &str| {
        path.rsplit_once('.')
            .map(|(_, extension)| extension.to_owned())
    };
    let extensions: BTreeSet<Option<String>> = missing
        .iter()
        .map(|&index| extension(drifts[index].path.file_name()))
        .collect();
    let planned: BTreeSet<&str> = plan
        .entries()
        .iter()
        .map(|entry| entry.path().as_str())
        .collect();
    let mut found: Vec<(usize, String)> = Vec::new();
    publisher.visit(true, &mut |relative, directory, name, kind| {
        if kind != FileType::RegularFile
            || manifest.owns(relative)
            || planned.contains(relative)
            || !extensions.contains(&extension(relative.rsplit('/').next().unwrap_or(relative)))
        {
            return Ok(());
        }
        let Some(bytes) = read_regular(directory, name, relative)? else {
            return Ok(());
        };
        let sha256 = hash_bytes(&bytes);
        let inv_id = marker::property(&bytes, "inv_id");
        for &index in &missing {
            let drift = &drifts[index];
            let same_file = drift.expected == sha256
                || drift
                    .projects
                    .is_some_and(|id| inv_id.as_deref() == Some(id.to_string().as_str()));
            if same_file && !drift.copies.iter().any(|copy| copy == relative) {
                found.push((index, relative.to_owned()));
            }
        }
        Ok(())
    })?;
    for (index, relative) in found {
        drifts[index].renamed_to.push(relative);
    }
    for &index in &missing {
        let drift = &mut drifts[index];
        if !drift.renamed_to.is_empty() {
            drift.renamed_to.sort();
            drift.kind = DriftKind::Renamed;
        }
    }
    Ok(())
}

/// Store the content each drift withheld under
/// `local/conflicts/<generation>/<path>` and set [`Drift::conflict`]. A file
/// an earlier render retained for the same path with the same hash is reused.
pub(crate) fn retain(
    workspace: &Workspace,
    previous: &Manifest,
    plan: &RenderPlan,
    drifts: &mut [Drift],
) -> Result<(), RenderError> {
    if drifts.iter().all(|drift| drift.generated.is_none()) {
        return Ok(());
    }
    let entries: BTreeMap<&PlanPath, &PlanEntry> = plan
        .entries()
        .iter()
        .map(|entry| (entry.path(), entry))
        .collect();
    let local = open_local(workspace.root())?;
    let generation = plan.generation().id();
    let tag = generation
        .trim_start_matches("gen_")
        .get(..12)
        .unwrap_or("render");
    for drift in drifts {
        let (Some(generated), Some(entry)) = (&drift.generated, entries.get(&drift.path)) else {
            continue;
        };
        if let Some(earlier) = previous
            .drifted(&drift.path)
            .filter(|earlier| earlier.generated.as_ref() == Some(generated))
            .and_then(|earlier| earlier.conflict.as_deref())
            && retained(&local, earlier)?.as_ref() == Some(generated)
        {
            drift.conflict = Some(earlier.to_owned());
            continue;
        }
        let relative = format!("{CONFLICTS_DIR}/{generation}/{}", drift.path.as_str());
        let mut components: Vec<&str> = relative.split('/').skip(1).collect();
        let name = components.pop().expect("conflict paths have a file name");
        let directory =
            conflicts_directory(&local, &components, true)?.expect("created directories exist");
        write_bytes_atomically(&directory, &relative, name, entry.content(), tag, true)?;
        drift.conflict = Some(relative);
    }
    Ok(())
}

/// The hash of a retained file, `None` when it is not there.
fn retained(local: &OwnedFd, relative: &str) -> Result<Option<Digest>, RenderError> {
    let Some(inside) = relative.strip_prefix("local/") else {
        return Ok(None);
    };
    let mut components: Vec<&str> = inside.split('/').collect();
    let name = components.pop().unwrap_or_default();
    let Some(directory) = conflicts_directory(local, &components, false)? else {
        return Ok(None);
    };
    Ok(read_regular(&directory, name, relative)?.map(|bytes| hash_bytes(&bytes)))
}

/// Open `components` below `local/` without following links, creating
/// missing folders (mode 0700) when `create`. `None` when a folder is
/// missing and `create` is false.
fn conflicts_directory(
    local: &OwnedFd,
    components: &[&str],
    create: bool,
) -> Result<Option<OwnedFd>, RenderError> {
    let flags = OFlags::DIRECTORY | OFlags::RDONLY | OFlags::NOFOLLOW | OFlags::CLOEXEC;
    let mut directory = openat(local, ".", flags, Mode::empty())
        .map_err(|error| RenderError::io("local", error))?;
    for component in components {
        let mut next = openat(&directory, *component, flags, Mode::empty());
        if create && matches!(next, Err(Errno::NOENT)) {
            match mkdirat(&directory, *component, Mode::from_raw_mode(0o700)) {
                Ok(()) | Err(Errno::EXIST) => {}
                Err(error) => return Err(RenderError::io(CONFLICTS_DIR, error)),
            }
            fsync(directory.as_fd()).map_err(|error| RenderError::io(CONFLICTS_DIR, error))?;
            next = openat(&directory, *component, flags, Mode::empty());
        }
        directory = match next {
            Ok(fd) => fd,
            Err(Errno::NOENT) => return Ok(None),
            Err(Errno::LOOP | Errno::NOTDIR) => {
                return Err(RenderError::UnsafeDirectory("workspace local/conflicts/"));
            }
            Err(error) => return Err(RenderError::io(CONFLICTS_DIR, error)),
        };
    }
    Ok(Some(directory))
}

/// The bytes of a regular file, read without following links; `None` when it
/// is absent, not a regular file or too large to be a note.
fn read_regular(
    directory: &OwnedFd,
    name: impl rustix::path::Arg,
    label: &str,
) -> Result<Option<Vec<u8>>, RenderError> {
    let fd = match openat(
        directory,
        name,
        OFlags::RDONLY | OFlags::NOFOLLOW | OFlags::NONBLOCK | OFlags::CLOEXEC,
        Mode::empty(),
    ) {
        Ok(fd) => fd,
        Err(Errno::NOENT | Errno::LOOP | Errno::NXIO) => return Ok(None),
        Err(error) => return Err(RenderError::io(label, error)),
    };
    let stat = fstat(&fd).map_err(|error| RenderError::io(label, error))?;
    if FileType::from_raw_mode(stat.st_mode) != FileType::RegularFile
        || stat.st_size as u64 > MAX_CANDIDATE_BYTES
    {
        return Ok(None);
    }
    let mut bytes = Vec::new();
    File::from(fd)
        .take(MAX_CANDIDATE_BYTES + 1)
        .read_to_end(&mut bytes)
        .map_err(|error| RenderError::io(label, error))?;
    if bytes.len() as u64 > MAX_CANDIDATE_BYTES {
        return Ok(None);
    }
    Ok(Some(bytes))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn conflict_copies_are_matched_by_stem_boundary_and_the_word_conflict() {
        let owned = "q_1.md";
        for copy in [
            "q_1 (conflicted copy 2026-01-02 101500).md",
            "q_1 (Conflict).md",
            "q_1.sync-conflict-20260102-101500-ABCDEFG.md",
            "q_1.md.conflict",
            "q_1-CONFLICT-laptop.md",
        ] {
            assert!(is_conflict_copy(copy, owned), "{copy}");
        }
        for other in [
            "q_1.md",
            "q_12 (conflict).md",
            "q_1 (1).md",
            "q_1 2.md",
            "Q_1 (conflict).md",
            "notes about q_1 conflict.md",
            "q_1conflict.md",
        ] {
            assert!(!is_conflict_copy(other, owned), "{other}");
        }
        assert!(is_conflict_copy(
            "Start Here (conflicted copy).md",
            "Start Here.md"
        ));
        assert!(is_conflict_copy("Map conflict.canvas", "Map.canvas"));
    }

    #[test]
    fn kinds_round_trip_through_their_names() {
        for kind in DriftKind::ALL {
            assert_eq!(DriftKind::parse(kind.as_str()), Some(kind));
        }
        assert_eq!(DriftKind::parse("conflict-copy"), None);
    }
}
